contract InvMutTest {
    C c;

    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient) public payable {
        require(true);

        uint256 beforeBalance = address(c).balance;
        uint256 recipientBefore = recipient.balance;

        bool reverted;
        c.withdrawAll(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            reverted ||
            (recipient.balance - recipientBefore == beforeBalance)
        );
    }

    receive() external payable {}
}

