        c = new C(address(this));
    }

    function _run(address recipient) internal {
        vm.assume(true);
        uint256 beforeBalance = address(c).balance;
        uint256 recipientBefore = recipient.balance;
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted ||
            (recipient.balance - recipientBefore == beforeBalance));
    }

    function testFuzz_run(address recipient) public {
        _run(recipient);
    }

    receive() external payable {}
}
